if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_110d2875782898a96e3a3229b5ccac82' and md5(to_jsonb(t)::text)='5953d1b7fa30a2ae647fcb578c0dc6e0')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_110d2875782898a96e3a3229b5ccac82';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_61b09f21613118e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nPincho de hierro · 1 po · 5 lb · 10 · 0.5 · 10\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_61b09f21613118e3$::jsonb,true),'{rules,definition,description}',$text_ca94dda6590b5857$[{"id":"official-table","rows":[["Pincho de hierro","1 po","5 lb","10","0.5","10"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_ca94dda6590b5857$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_110d2875782898a96e3a3229b5ccac82';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_54dfc3b2e9967a5866a8898a5654c8c5' and md5(to_jsonb(t)::text)='00badd8d8bcc121bdfd8675aac3ad8cb')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_54dfc3b2e9967a5866a8898a5654c8c5';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_a1570cd70d2f5f70$"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos."$text_a1570cd70d2f5f70$::jsonb,true),'{features}',$text_af3cf1a757f09185$[{"id":"reserve-crystal","kind":"other","name":"Reserva arcana y descarga","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos.\n\nTres opciones de gasto 1/2/3; registrar por separado la corrupción MC, la ventana de 10 minutos, identificación, destrucción y uso en mecanismos. No sustituir la descarga por un conjuro oficial ni descartar sus costes de campaña.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_af3cf1a757f09185$::jsonb,true),'{rules,definition,description}',$text_5b8325390af9ea64$[{"id":"campaign-text-0","text":"Lente de cristal pesado, atravesado por vetas rojas que chisporrotean con energía arcana inestable. Estos cristales eran utilizados como acumuladores de poder en los antiguos dispositivos del Corazón, diseñados para almacenar, liberar y amplificar energía mágica.\n\nMecánica\nCargas: 3. Recupera 1d3 cargas al amanecer.\n\nUsos\n• 1 carga: lanzar un conjuro de 1.er nivel sin gastar ranura.\n• 2 cargas: lanzar un conjuro de 2.º nivel sin gastar ranura.\n• 3 cargas: descarga equivalente a Rayo abrasador (3 rayos de 2d6 de daño de fuego).\n\nCorruptibilidad\n• +1 MC por cada uso ofensivo o de manipulación mental.\n• Si se vacían todas las cargas en menos de 10 minutos: +2 MC.\n\nIdentificación\nArcana CD 16.\n\nDestrucción\nRomperlo con más de 30 puntos de daño contundente lo neutraliza, liberando 4d6 de energía elemental (CON CD 15, mitad con éxito).\n\nUso en mecanismos\nAl insertarlo en un receptáculo, aumenta drásticamente la potencia del artefacto: por ejemplo, un puente que se abría 3 m puede abrirse 9 m y activar guardianes antiguos.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_5b8325390af9ea64$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_54dfc3b2e9967a5866a8898a5654c8c5';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_5ec27f6fae673969edca3f3a8386a458' and md5(to_jsonb(t)::text)='1a638013af1cc09a0ffc23fd7e3438a5')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_5ec27f6fae673969edca3f3a8386a458';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_d1ecfa231bd5fa2d$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nEspada corta feroz · 10 po (solo objeto mundano base; no es el precio de la variante mágica) · 2 lb · 1d6 perforante · Sutil, Ligera · +0\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_d1ecfa231bd5fa2d$::jsonb,true),'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_9f9043892b11f9c3$[{"id":"official-table","rows":[["Espada corta feroz","10 po (solo objeto mundano base; no es el precio de la variante mágica)","2 lb","1d6 perforante","Sutil, Ligera","+0"]],"type":"table","columns":["Objeto","Precio base","Peso","Daño base","Propiedades","Bonificación mágica"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"vicious-2014","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_9f9043892b11f9c3$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6851a11da4c0ecd0$["official-table","vicious-2014"]$text_6851a11da4c0ecd0$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_5ec27f6fae673969edca3f3a8386a458';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_6612d379d91199e1a09f0054f73afe78' and md5(to_jsonb(t)::text)='c3a788bedd08ec4015c89b7033574ef6')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_6612d379d91199e1a09f0054f73afe78';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_038a74766038eaf3$"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas."$text_038a74766038eaf3$::jsonb,true),'{features}',$text_3e786f0a1bd7f240$[{"id":"consume-crystal","kind":"other","name":"Consumir cristal: elegir un efecto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas.\n\nElegir recuperación de espacio de nivel 1 o 2d6 PG temporales (con 1d4 de curación solo en el templo). No aplicar ambas opciones. Conservar corrupción, destrucción y uso de tres fragmentos en mecanismos.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3e786f0a1bd7f240$::jsonb,true),'{rules,definition,description}',$text_0cd83eeefae6555b$[{"id":"campaign-text-0","text":"Pequeño fragmento de cristal translúcido, similar al hielo claro, que pulsa con una luz interna tenue y constante. Son restos del banco energético del Corazón, un artefacto aeloriano que alimentaba el templo y sus mecanismos internos.\n\nMecánica\nUsar: acción. El fragmento se consume.\n\nEfecto (elige uno)\n• Recarga menor: restaura una ranura de conjuro de 1.er nivel (no rituales).\n• Pulso vital: otorga 2d6 puntos de golpe temporales a una criatura y cura 1d4 adicionales si se usa dentro del templo.\n\nCorruptibilidad\n• +1 MC si se activa tras derramar sangre o si se consumen varios fragmentos en una misma escena.\n\nIdentificación\nArcana CD 12 o Identificar.\n\nDestrucción\nAplastarlo (Fuerza CD 10) libera un pulso de 1d6 de daño radiante en un cono de 3 m, sin dañar objetos mágicos.\n\nUso en puzzles o artefactos\nTres fragmentos insertados en receptáculos del Corazón activan mecanismos menores como puertas, puentes o plataformas antiguas.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_0cd83eeefae6555b$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_6612d379d91199e1a09f0054f73afe78';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_9d6aa791ef793353a533cb45401d1be0' and md5(to_jsonb(t)::text)='363fbd1f44e4134b36b22a1a599f1cca')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_9d6aa791ef793353a533cb45401d1be0';end if;update public.campaign_state_fragments set payload=jsonb_set(payload,'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_9d6aa791ef793353a533cb45401d1be0';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_cb929039c8d785ffd3fe16c0a770ea6f' and md5(to_jsonb(t)::text)='eec610e2f8180bfa0b852d8b858403eb')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_cb929039c8d785ffd3fe16c0a770ea6f';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_60b95eb2fb6d1dcd$"Objeto · Precio base · Peso\nTúnica · 1 po · 4 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_60b95eb2fb6d1dcd$::jsonb,true),'{rules,definition,description}',$text_b300c24e82c4c95a$[{"id":"official-table","rows":[["Túnica","1 po","4 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_b300c24e82c4c95a$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_cb929039c8d785ffd3fe16c0a770ea6f';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_d4bc3a889409ff88865ba0e0633d39fb' and md5(to_jsonb(t)::text)='01315e0b6c68e5b735099e825990af3d')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_d4bc3a889409ff88865ba0e0633d39fb';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_6e5705a1601f9f6e$[{"id":"phase-blade","kind":"other","name":"Hoja Fásica · Stix","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"1d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"shadow-step","kind":"bonus-action","name":"Salto entre Sombras","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nTeletransporte hasta 15 pies a espacio desocupado visible, sin ataques de oportunidad; una vez por descanso corto o largo.\n\nDuración: Instantánea.\n\nAlcance: 15 pies.\n\nCoste: 1 salto.","showInActions":true}]$text_6e5705a1601f9f6e$::jsonb,true),'{rules,personalDescription}',$text_7d0ad9435aca71d9$"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."$text_7d0ad9435aca71d9$::jsonb,true),'{catalog,revision}',$text_b17ef6d19c7a5b1e$16$text_b17ef6d19c7a5b1e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_d4bc3a889409ff88865ba0e0633d39fb';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_f3451ccfa101847572eed1826f0164f1' and md5(to_jsonb(t)::text)='8bb7551fe2a8d61d1360c4b8513f88a8')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_f3451ccfa101847572eed1826f0164f1';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{features}',$text_ae23ed56aa8fbde8$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, tus pasos no harán ruido, independientemente de la superficie que pises. También tendrás ventaja en las pruebas de Destreza (Sigilo) que requieran moverse sin hacer ruido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_ae23ed56aa8fbde8$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_2de8dab74a76cdd8d2b0d37cc84725ea' and entity_id='inv_f3451ccfa101847572eed1826f0164f1';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_31b5cf3abda27cf3910182c6e1a6f82e' and entity_id='inv_329544edb4402c093443542da4598c57' and md5(to_jsonb(t)::text)='5067485a7829b474ea7bf3aec8307fde')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_329544edb4402c093443542da4598c57';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_57ad9bd72f8bcb37$"Objeto · Precio base · Peso\nAntorcha · 1 pc · 1 lb\n\nAntorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_57ad9bd72f8bcb37$::jsonb,true),'{features}',$text_de7c9fd07470e6fa$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_de7c9fd07470e6fa$::jsonb,true),'{rules,definition,description}',$text_5a4b49e76e85ed57$[{"id":"official-table","rows":[["Antorcha","1 pc","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_5a4b49e76e85ed57$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_31b5cf3abda27cf3910182c6e1a6f82e' and entity_id='inv_329544edb4402c093443542da4598c57';
