if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_345a4e8763475f1c2acbd5c2a56bcf36' and entity_id='inv_093a211c1bc85c9f07c0d821f8f8741b' and md5(to_jsonb(t)::text)='25f8e2ff657d47590aa7fe9cd9baa97d')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_093a211c1bc85c9f07c0d821f8f8741b';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition,description}',$text_88442117174e3b38$[{"id":"current-description","text":"Objeto narrativo sin propiedades mecánicas.","type":"paragraph","section":"description","sourceIds":["ece-current-copy"],"provenance":"campaign"},{"id":"recovered-campaign-description","text":"Fragmento de Cristal Luciente Negro\nEste objeto no posee propiedades mecánicas importantes.\nPero sí enorme valor narrativo.\nMaelion lo recuperó en una ruina profunda de la Infraoscuridad.\nEl cristal:\nemite una luz muy tenue;\nreacciona débilmente a la magia;\nposee vetas internas similares a las observadas en cristales lucientes de superficie.\nCuando Severino lo observa por primera vez durante la expedición, queda profundamente intrigado.\nEste fragmento constituye una de las primeras pistas de que los cristales lucientes existen tanto en la superficie como en las profundidades del mundo, y puede convertirse en una pieza importante para futuras conexiones entre la Infraoscuridad, el Eco y el legado aeloriano.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$text_88442117174e3b38$::jsonb,true),'{catalog,revision}',$text_6b86b273ff34fce1$1$text_6b86b273ff34fce1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_d18eb8837908ca8b$["current-description","recovered-campaign-description"]$text_d18eb8837908ca8b$::jsonb?id),jsonb_build_array('current-description')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_345a4e8763475f1c2acbd5c2a56bcf36' and entity_id='inv_093a211c1bc85c9f07c0d821f8f8741b';
